local targetScene = "DreamSpaceLvl2_Demo"




-- ========================================================

function SingleLuaScene_LoadFromGameEntry:__init()

    self.frameCount = 0
    self.isUINavigationBarRootClosed = false

    self.controller = nil
    self.co = nil   -- 发送携程请求
end


function SingleLuaScene_LoadFromGameEntry:__delete()

    self.co = nil
end



function SingleLuaScene_LoadFromGameEntry:Awake()
    KTool.SetActive(self.controller.gameObject, true);

    self.uiRoot = SingleLuaScene_LoadFromGameEntry.FindRootTransformInTgtScene(scene_GameEntry, "UIRoot" )
    assert( isNotNull(self.uiRoot) )

    --- 关闭 游戏入场动画:
    local GameInit = self.uiRoot.transform:Find("UIRootCanvas/GameInit")
    assert( isNotNull(GameInit) )
    KTool.SetActive( GameInit.gameObject, false )

    --- 关闭 登录 ui 界面:
    local PassportDialog = self.uiRoot.transform:Find("UIRootCanvas/PassportDialog")
    assert( isNotNull(PassportDialog) )
    KTool.SetActive( PassportDialog.gameObject, false )

    --- 开启 主相机:
    local mCamera = URPCameraController.mainCamera
    assert( isNotNull(mCamera) )
    KTool.SetActive( mCamera.gameObject, true )


    -- 加载 DreamSpace 单lua测试场景:
    SceneManager.sceneLoaded('+', function(scene_, mode_)
        SceneManager.SetActiveScene( scene_ )  
    end )
    SceneManager.LoadScene(targetScene, LoadSceneMode.Additive);


    -- 解决 "存在两个 EventSystem" 的问题:
    local EventSystem = self.uiRoot.transform:Find("EventSystem")
    assert( isNotNull(EventSystem) )
    KTool.SetActive( EventSystem.gameObject, false )

end





function SingleLuaScene_LoadFromGameEntry:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ==============================

end




function SingleLuaScene_LoadFromGameEntry:OnDestroy()



    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    print("   ~~~~~~~ SingleLuaScene_LoadFromGameEntry:OnDestroy() ~~~~~~~")
end


-- =============================================================== Self -> ================================================================== -- 


function SingleLuaScene_LoadFromGameEntry:Update()
    

    if self.isUINavigationBarRootClosed ~= true then 
        self.frameCount = self.frameCount + 1
        if self.frameCount % 21 == 0  then 
            
            --- 为了隐藏掉 左上角的 返回按钮:
            local UINavigationBarRoot = self.uiRoot.transform:Find("UIRootCanvas/UINavigationBarRoot")
            if isNotNull(UINavigationBarRoot) then 
                KTool.SetActive( UINavigationBarRoot.gameObject, false )
                self.isUINavigationBarRootClosed = true
            end 
        end
    end 

end






-- 遍历 目标场景 顶层 GOs, 找出其中名字为 参数 name_ 的 gameobj:
function SingleLuaScene_LoadFromGameEntry.FindRootTransformInTgtScene( sceneName_, name_)
    local tgtScene = SceneManager.GetSceneByName(sceneName_)
    if isNull(tgtScene) then 
        printError("koko - 没找到场景 (1): " .. tostring(sceneName_))
        return nil
    end 

    if tgtScene:IsValid() and tgtScene.isLoaded then 

        local rootObjects = tgtScene:GetRootGameObjects() -- GameObject[]
        for i=0,rootObjects.Length-1 do
            local go = rootObjects[i]
            if isNotNull(go) and go.name == tostring(name_) then 
                return go.transform
            end 
        end
    else 
        printError("koko - 异常, 爱豆场景未加载 (2)")
    end 
    printError("koko - 异常, 未找到 " .. tostring(name_) .. " 这个根节点")
    return nil
end













return SingleLuaScene_LoadFromGameEntry
